'use strict';
const $ = id => document.getElementById(id);
const stage=$('stage');
let nativeAPI=null, snapshot=null, activeView='chat', mode='General Assist', currentJob=null, handledJob=null, lastReview=null, gitProposal=null, pendingId=null, polling=false, settingsReview=null, pluginReview=null;
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function scaleUI(){const fit=Math.min(innerWidth/1672,innerHeight/1010);const mode=document.documentElement.dataset.layout||'fit';const scale=mode==='fit'?fit:Math.max(fit,mode==='large'?1.25:1);stage.style.transform=`scale(${scale})`;stage.style.left=`${Math.max(0,(innerWidth-1672*scale)/2)}px`;stage.style.top=`${Math.max(0,(innerHeight-1010*scale)/2)}px`;const extent=document.getElementById('desktop-extent');if(extent){extent.style.width=`${1672*scale}px`;extent.style.height=`${1010*scale}px`;}}
addEventListener('resize',scaleUI);scaleUI();
function toast(message){$('desktop-announcement')&&($('desktop-announcement').textContent=message);$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500);}
async function call(name,...args){if(!nativeAPI)throw new Error('The desktop bridge is not connected. Start the app with Run-PurpleDragonAI.bat.');const origin=activeView;const result=await nativeAPI[name](...args);if(result.ok&&name==='save_settings'&&origin===activeView)rememberSavedSettings(args[0]);if(result.ok&&['save_settings','choose_workspace'].includes(name)){if($('model-context-panel')){$('model-context-panel').hidden=true;$('model-context-text').textContent='';}researchPreview=null;lastReview=null;gitProposal=null;settingsReview=null;pluginReview=null;}return result;}
function timeLabel(date){const d=new Date(date);if(Number.isNaN(d.getTime()))return '';return d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}
function addMessage(role,text){const item=document.createElement('div');item.className=`message ${role}`;const avatar=document.createElement('div');avatar.className=`avatar sprite ${role==='user'?'user-avatar':'dragon-avatar'}`;const bubble=document.createElement('div');bubble.className='bubble';const meta=document.createElement('div');meta.className='message-meta';const name=document.createElement('strong');name.textContent=role==='user'?'You':'Purple Dragon AI';const time=document.createElement('time');time.textContent=timeLabel(new Date());meta.append(name,time);const body=document.createElement('div');body.className='message-text';body.textContent=text;bubble.append(meta,body);item.append(avatar,bubble);$('conversation').append(item);$('conversation').scrollTop=$('conversation').scrollHeight;return body;}
function resultText(result){let text=result.message||'Operation finished.';if(result.data?.diff&&result.data?.id)return text+'\n\n'+result.data.diff;if(result.data!=null){if(Array.isArray(result.data)&&result.data[0]?.result){for(const row of result.data){text+=`\n\n${row.step.tool}: ${row.result.message}`;if(row.result.data!=null)text+='\n'+JSON.stringify(row.result.data,null,2);}}else{text+='\n\n'+(typeof result.data==='string'?result.data:JSON.stringify(result.data,null,2));}}return text;}
let chatSubmitting=false;
async function submit(){if(chatSubmitting)return;if(activeView!=='chat'&&hasUnsavedForm()){protectUnsaved(()=>{view('chat',true);submit();});return;}const task=$('prompt').value.trim();if(activeView!=='chat')view('chat');if(!task)return $('prompt').focus();if(snapshot?.busy)return toast('Wait for the current task to finish.');chatSubmitting=true;try{const kind=mode==='Creative Tools'?'draft':'task';const conversation_id=await ensureConversation();const result=await call('start_job',kind,{task,conversation_id});if(!result.ok)return toast(result.message);addMessage('user',task);currentJob={id:result.id,name:'task',view:'chat',body:addMessage('assistant','Working…')};$('prompt').value='';$('send').disabled=true;await poll();}catch(error){toast(error.message);}finally{chatSubmitting=false;}}
$('send').addEventListener('click',submit);$('prompt').addEventListener('keydown',event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();submit();}});
function patchState(s){if(snapshot&&snapshot.workspace!==s.workspace){lastReview=null;gitProposal=null;settingsReview=null;pluginReview=null;}snapshot=s;stage.classList.toggle('native-window-frame',s.native_window_frame===true);$('footer-workspace-name').textContent=s.workspace.split(/[\\/]/).filter(Boolean).pop()||'Workspace';$('footer-workspace').title=s.workspace;$('model-name').textContent=s.model_enabled?s.model:'Purple Dragon AI';const connection=s.connection||{};const verified=s.model_enabled&&connection.status==='verified';$('online').classList.toggle('connected',verified);$('online').lastElementChild.textContent=verified?'Verified':s.model_enabled?'Local':'Fallback';$('online').title=connection.checked_at?'Last checked '+connection.checked_at:'Not tested in this session';$('gate-value').textContent=s.busy?'APPROVALS ON':'SAFE MODE';$('file-value').textContent=s.files==null?'Not indexed':`${s.files} file(s)`;$('time-value').textContent=s.duration==null?'—':`${s.duration}s last`;$('policy-value').textContent=`${s.asks} Ask · ${s.denies} Deny`;$('model-value').textContent=verified?'VERIFIED':s.model_enabled?(connection.status==='error'?'ERROR':'CONFIGURED'):'FALLBACK';$('model-value').classList.toggle('green',verified);$('local-model-detail').replaceChildren(document.createTextNode(s.model_enabled?s.model:'Fallback Planner'),document.createElement('br'));const detail=document.createElement('span');detail.textContent=verified?'Last inference test passed':s.model_enabled?(connection.status==='error'?'Connection test failed':'Local connector · unverified'):'LM Studio connector disabled';$('local-model-detail').append(detail);$('running-pill').textContent='◆ SAFE MODE';$('queue-pill').textContent=s.busy?(s.job?.kind==='team'&&s.team?.state==='paused'?'1 PAUSED':'1 RUNNING'):'0 RUNNING';$('queue-label').textContent=s.busy?(s.connection?.busy?'Local connection check':s.job?.label||'Working'):'No active task';$('queue-state').textContent=s.approval?'Approval…':s.busy?(s.job?.kind==='team'&&s.team?.state==='paused'?'Paused':s.job?.kind==='team'&&s.team?.state==='pausing'?'Pausing…':s.job?.kind==='team'&&s.team?.state==='cancelling'?'Stopping…':'Running…'):'Idle';$('send').disabled=s.busy;const events=(s.events||[]).slice().reverse().slice(0,5);$('recent-actions').replaceChildren(...events.map(row=>{const line=document.createElement('div');const dot=document.createElement('span');dot.className='event-dot';dot.textContent='⊙';const title=document.createElement('span');title.className='event-name';title.textContent=row.event.replace(/_/g,' ');const time=document.createElement('time');time.textContent=timeLabel(row.timestamp);line.append(dot,title,time);return line;}));if(!events.length){$('recent-actions').textContent='No actions recorded';}
 conversationState(s);
 updateConnectionPanel(connection);
 updateTeam(s.team);
 window.updatePlatformStatus?.(s.platform_status);
 updateSecurity(s.security);
 document.querySelectorAll('[data-action="run-tests"],[data-action="preview-tests"]').forEach(button=>button.disabled=s.runner?.execution_available===false);
 if(s.job?.state==='finished'&&s.job.id!==handledJob){const result=s.job.result;const matching=currentJob?.id===s.job.id;if(matching){if(currentJob.name==='recovery_trust'&&activeView==='recovery')$('release-trust-report').textContent=resultText(result);$('desktop-announcement').textContent=result.message||'Operation finished.';handledJob=s.job.id;if(currentJob.body)renderChatText(currentJob.body,resultText(result));handleValidationResult(currentJob,result);handleKnowledgeResult(currentJob,result);if(currentJob.name==='review_changes'&&result.ok){lastReview=result.data;renderWorkspaceReview(result.data);}if(currentJob.name==='git_preview'&&result.ok){gitProposal=currentJob.reviewKey===gitFormKey()?result.data:null;}if(currentJob.name==='git_execute')gitProposal=null;if(currentJob.name==='recovery_preview_restore'||currentJob.name==='recovery_preview_reset'){if(result.ok)settingsReview=currentJob.name==='recovery_preview_reset'||currentJob.reviewKey===$('settings-backup-id')?.value.trim()?result.data:null;}if(currentJob.name==='recovery_restore')settingsReview=null;if(currentJob.name==='recovery_list_backups'&&result.ok&&activeView==='recovery')renderBackups(result.data);if(currentJob.name==='plugin_preview'&&result.ok){pluginReview=currentJob.reviewKey===pluginFormKey()?result.data:null;if(!pluginReview)toast('Plugin inputs changed. Prepare a new review.');}if(currentJob.name==='plugin_execute')pluginReview=null;const out=$('tool-output');if(out&&activeView===currentJob.view){out.textContent=currentJob.name==='review_changes'&&result.ok?'Full review shown below. Proposal '+result.data.id+' · '+result.data.paths.length+' file(s). Inspect every diff before applying.':resultText(result);out.className=`tool-result ${result.ok?'success':'error'}`;}if(['read_file','preview_file'].includes(currentJob.name)&&result.ok&&activeView==='workspace'&&$('file-content')){if(currentJob.editorKey===workspaceEditorKey()){$('file-content').value=typeof result.data==='string'?result.data:(result.data?.content||'');rememberForm();}else toast('File read finished, but the editor changed. Your edits were kept. Read again when ready.');}if(currentJob.name==='list_files'&&result.ok&&activeView==='workspace')renderFiles(result.data);if(currentJob.name==='list_memory'&&result.ok&&activeView==='memory')renderMemory(result.data);if(currentJob.name==='list_web_sources'&&result.ok&&activeView==='research')renderSources(result.data);currentJob=null;} }
 renderTestRunner(s.runner);
 workspaceState(s);
 if(s.approval){window.closeDesktopForApproval?.();if(pendingId!==s.approval.id){pendingId=s.approval.id;$('approval-action').textContent=s.approval.action.replace(/_/g,' ');$('approval-context').textContent=JSON.stringify(s.approval.context,null,2);window.closeGuideForApproval?.();if(!$('approval').open)$('approval').showModal();$('deny').focus();}}else{pendingId=null;if($('approval').open)$('approval').close();}}
async function poll(){if(polling||!nativeAPI)return;polling=true;try{patchState(await call('state'));}catch(error){toast(error.message);}finally{polling=false;}}
async function resolve(approved){if(!pendingId)return;try{const result=await call('resolve_approval',pendingId,approved);if(!result.ok)toast(result.message);await poll();}catch(error){toast(error.message);}}
$('allow').addEventListener('click',()=>resolve(true));$('deny').addEventListener('click',()=>resolve(false));$('approval').addEventListener('cancel',event=>{event.preventDefault();resolve(false);});
function field(label,id,type='text',value='',placeholder=''){return `<label class="field">${esc(label)}<${type==='textarea'?'textarea':'input'} id="${id}" ${type!=='textarea'?`type="${type}" value="${esc(value)}"`:''} placeholder="${esc(placeholder)}">${type==='textarea'?esc(value)+'</textarea>':''}</label>`;}
const button=(label,action)=>`<button class="action" data-action="${action}">${label}</button>`;
const output=()=>'<pre id="tool-output" class="tool-result">Select a tool to begin. Operations follow the existing permission gateway.</pre>';
const tabs=()=>'<div class="route-tabs">'+['workspace','coding','terminal','research','permissions','activity','git','security','recovery'].map(v=>`<button class="action" data-view="${v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')+'</div>';
function renderView(name){activeView=name;const chat=name==='chat';$('conversation-bar').hidden=!chat;$('route-view').hidden=chat;$('chat-view').hidden=false;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===(chat?'chat':['workspace','coding','terminal','research','permissions','activity','git','security','recovery'].includes(name)?'tools':name)));if(chat){$('prompt').focus();return;}const body=$('route-body');const titles={agents:'AGENT PLANNING CENTER',tools:'PURPLE DRAGON AI AGENT 2.0',workspace:'WORKSPACE',coding:'CODE ASSISTANT',terminal:'TERMINAL & TESTS',research:'RESEARCH AGENT',plugins:'PLUGINS',memory:'PROJECT MEMORY',settings:'SETTINGS',permissions:'PERMISSION POLICIES',activity:'RECENT ACTIONS',git:'GIT + GITHUB AGENT',security:'SECURITY, SANDBOX & PERMISSIONS',recovery:'RELEASE CANDIDATE & RECOVERY'};$('route-title').textContent=titles[name]||name.toUpperCase();
 if(name==='agents'){body.innerHTML=`<p class="fine">Review the fixed sequential plan before starting. Roles share the existing permission gateway. No automatic application or publishing.</p>${field('Plan goal','team-task','textarea')}${field('Selected files (one per line)','team-paths','textarea')}${field('Cached research source IDs (one per line)','team-sources','textarea')}<div class="route-tabs">${['Coding','Research','QA','Security','Release'].map(r=>`<label><input type="checkbox" data-role="${r}" checked> ${r}</label>`).join('')}</div><p><label><input id="team-propose" type="checkbox"> Ask Coding to stage a model proposal</label></p><p><label><input id="team-tests" type="checkbox"> Run QA host tests with separate approval (current files only)</label></p><div class="route-tabs">${button('Prepare plan · no tools','prepare-team')}${button('Start reviewed plan','start-team')}${button('Pause after current tool','pause-team')}${button('Resume plan','resume-team')}${button('Cancel plan','cancel-team')}</div><div class="route-tabs">${button('Prepare failed-step retry','prepare-team-retry')}${button('Start reviewed retry','retry-team')}</div><div id="team-plan-review"></div><div id="team-progress" role="status"></div><div id="team-steps"></div><h3>Role handoffs & evidence</h3><pre id="team-live" class="tool-result"></pre>${output()}`;initializePlanningView();updateTeam(snapshot?.team);}

 else if(name==='tools'){body.innerHTML=tabs()+platformCenterMarkup()+`<details class="tool-card"><summary>Advanced tool arguments</summary><p class="fine">Use focused sections above for guided workflows. These arguments still go through the same permission gateway.</p><label class="field">Operation<select id="advanced-name">${Object.keys(examples).map(k=>`<option>${k}</option>`).join('')}</select></label>${field('Operation arguments','advanced-args','textarea','{}')}${button('Preview / execute selected operation','advanced')}</details>`+output();$('advanced-name').addEventListener('change',()=>{$('advanced-args').value=JSON.stringify(examples[$('advanced-name').value],null,2);});loadPlatformCenter();}
 else if(name==='git'){gitProposal=null;body.innerHTML=tabs()+`<div class="tool-card"><h2>Repository workspace</h2>${field('Repository folder inside the workspace','git-repo','text','.')}<div class="route-tabs">${button('Inspect repository','git-status')}${button('Working diff','git-diff')}${button('Staged diff','git-staged')}</div><p class="fine">Git must be installed. Select the repository root, not a linked worktree. Repository hooks, external diff helpers and arbitrary commands are disabled.</p></div><div class="tool-card"><label class="field">Operation<select id="git-operation"><option value="branch">Create branch (without switching)</option><option value="commit">Commit already-staged changes</option><option value="push">Push reviewed commit to GitHub</option><option value="pr">Create pull request</option><option value="release">Create GitHub release</option></select></label><div class="form-grid">${field('New branch name','git-branch')}${field('PR base branch','git-base','text','main')}${field('Commit message','git-message')}${field('PR / release title','git-title')}${field('Release tag','git-tag')}</div>${field('PR description / release notes','git-body','textarea')}<label><input id="git-draft" type="checkbox" checked> Create a draft release</label><div class="route-tabs" style="margin-top:15px">${button('Prepare review · no writes','git-preview')}${button('Execute reviewed proposal','git-execute')}</div><p class="fine">Commits use only files already staged in your Git client and a repository-local author identity. PRs require the reviewed branch to be pushed. Push and release policies start at Deny; select Ask in Permissions to enable their approval gates. Remote operations also require GitHub network approval and an externally authenticated GitHub CLI.</p></div>`+output();for(const input of body.querySelectorAll('input,textarea,select'))input.addEventListener('input',()=>{gitProposal=null;});}
 else if(name==='workspace'){body.innerHTML=tabs()+`<div class="tool-card"><header><h2>Project files</h2><div>${button('Choose folder','choose-workspace')} ${button('Refresh files','list-files')}</div></header><p class="fine">${esc(snapshot?.workspace||'')}</p><label class="field">Search file paths<input id="file-search" type="search" maxlength="200" placeholder="Filter listed paths, e.g. tests/ or .py"></label><p id="file-list-summary" class="fine"></p><div id="files-list"></div><div id="selected-context"></div><div class="route-tabs"><button class="action" id="context-to-coding">Use selection in Coding →</button><button class="action" id="context-clear">Clear selection</button></div><p class="fine">Select at most 8 files. Selection alone sends no file content to a model. Coding reads selected sources through the permission gateway and enforces its source-size limit.</p></div><div class="tool-card">${field('Relative file path','file-path')}${field('File content / proposed replacement','file-content','textarea')}<div class="route-tabs">${button('Read file','read-file')}${button('Stage changes','stage-file')}${button('Review full diff','review')}${button('Apply reviewed changes','apply')}${button('Discard proposal','discard')}${button('Create snapshot','snapshot')}</div></div>`+output();}
 else if(name==='coding'){body.innerHTML=tabs()+`<div class="tool-card">${field('Selected source paths (one per line)','code-paths','textarea')}${field('Change instructions','code-instruction','textarea')}<div class="route-tabs">${button('Validate selected sources','analyze-code')}${button('Propose staged changes','propose-code')}${button('Review full diff','review')}${button('Apply reviewed changes','apply')}</div><p class="fine">Validate the exact selected sources before generating. Syntax errors in current source can be repaired; generated Python/JSON replacements must parse before any file is staged. Other languages require manual syntax review. Tests execute current files on disk, never unapplied proposals. Apply requires a current reviewed diff and separate approval.</p><div id="coding-validation"></div><div id="coding-proposal"></div></div>`+output();initializeValidationView();}
 else if(name==='terminal'){body.innerHTML=tabs()+`<div class="tool-card"><h2>Controlled test runner</h2><p>${snapshot?.runner?.execution_available===false?'Host tests are unavailable in this packaged runtime. Use the source installation with normal Python.':'Preview the fixed Python test command before execution. Host tests always require explicit approval.'}</p><div class="form-grid"><label class="field">Framework<select id="test-framework"><option value="auto">Auto detect</option><option value="unittest">unittest</option><option value="pytest">pytest · requires installed package</option></select></label>${field('Test timeout · 1 to 600 seconds','test-timeout','number',120)}</div><p class="fine">Host tests run current files on disk with your account access. Unapplied staged changes are excluded. Preview the command after changing these options. No packages are installed automatically.</p><div class="route-tabs">${button('Detect framework','detect-tests')}${button('Preview command','preview-tests')}${button('Run approved tests','run-tests')}${button('Cancel test process','cancel-tests')}</div><div id="test-summary"></div><button class="action" id="copy-test-summary">Copy shown test summary</button><h3>Live output</h3><pre id="runner-output" class="tool-result">${esc(JSON.stringify(snapshot?.runner||{},null,2))}</pre></div>`+output();initializeValidationView();}
 else if(name==='research'){body.innerHTML=tabs()+`<div class="tool-card"><p class="fine">Research is off by default. Fetch requires configured domain/network policy and approval. Cached-source previews perform no network request.</p>${field('Public HTTPS URL','research-url','url','','https://example.com/')}<div class="route-tabs">${button('Preview URL policy','preview-url')}${button('Fetch approved source','fetch-url')}${button('Load cached sources','list-sources')}</div><div id="source-list"></div><div id="cached-source-detail"></div></div><div class="tool-card">${field('Selected cached source IDs · up to five','source-ids','textarea')}${field('Research question','research-question','textarea')}<div class="route-tabs">${button('Preview exact research context','research-context')}${button('Create cited draft','research-brief')}${button('Last attempted model request','model-context')}</div><div id="research-context-preview"></div><div id="research-draft"></div></div>`+output();initializeKnowledgeView();}
 else if(name==='plugins'){pluginReview=null;body.innerHTML=`<div class="tool-card"><h2>Plugin API v1 · controlled workflows</h2><p class="fine">Local JSON manifests declare fixed tools and explicit inputs. No scripts, shell, module imports or remote plugins are loaded. Review execution scope, then approve the workflow; every tool retains its own permission gates.</p>${button('List local plugins','plugin-list')}${field('Plugin ID','plugin-id','text','workspace-overview')}${field('Explicit inputs · JSON object','plugin-inputs','textarea','{}')}<div class="route-tabs">${button('Prepare tool review','plugin-preview')}${button('Run reviewed workflow','plugin-run')}${button('Cancel workflow','plugin-cancel')}</div><p class="fine">Bundled IDs: workspace-overview ({}), source-review ({"paths":["source.py"]}). API contract: PLUGIN-API-v1.md. Only one controlled job runs at a time.</p></div>`+output();$('plugin-id').addEventListener('input',()=>pluginReview=null);$('plugin-inputs').addEventListener('input',()=>pluginReview=null);}
 else if(name==='memory'){body.innerHTML=`<div class="tool-card"><header><h2>Project knowledge</h2>${button('Search / refresh memory','list-memory')}</header><div class="form-grid">${field('Search title and body','memory-query')}<label class="field">Show<select id="memory-filter"><option value="saved">Notes & decisions</option><option value="all">All including history</option><option value="note">Notes</option><option value="decision">Decisions</option><option value="history">Task history</option></select></label></div><div id="memory-list"></div></div><div class="tool-card"><h3 id="memory-edit-status">New note</h3><label class="field">Kind<select id="memory-kind"><option value="note">Note</option><option value="decision">Decision</option></select></label>${field('Title','memory-title')}${field('Body','memory-body','textarea')}<div class="route-tabs">${button('Save with approval','save-memory')}${button('New note','memory-new')}</div><p class="fine">Editing checks the reviewed revision. An age warning is a reminder to review, not proof information is wrong. Saving an unchanged reviewed entry updates its revision/date.</p></div><div class="tool-card"><h3>Project-memory context preview</h3><p class="fine">Model memory use is ${snapshot?.config?.project_memory?.use_context?'enabled':'disabled'} in Settings. Preview uses this exact query and the current policy; actual requests recompute memory. Use the outgoing receipt to inspect an attempted request.</p>${field('Exact task / query to preview','memory-context-query','textarea')}<div class="route-tabs">${button('Preview selected memory','memory-context')}${button('Last attempted model request','model-context')}</div><pre id="memory-context-preview" class="tool-result">No preview requested.</pre></div>`+output();initializeKnowledgeView();}
 else if(name==='settings'){const c=snapshot?.config||{};const lm=c.lm_studio||{};const research=c.research||{};body.innerHTML=`<div class="tool-card"><h2>Local model connection</h2><label class="field"><span><input type="checkbox" id="lm-enabled" ${lm.enabled?'checked':''} style="width:auto"> Enable LM Studio connector</span></label><div class="form-grid">${field('Local endpoint','lm-endpoint','text',lm.endpoint||'http://127.0.0.1:1234/v1/chat/completions')}${field('Model identifier','lm-model','text',lm.model||'local-model')}</div><label class="field">Models reported by the saved local server<select id="available-models"><option value="">Refresh models to load this list</option></select></label><div class="route-tabs">${button('Refresh models / test server','refresh-models')}${button('Test selected model','test-model')}</div><div id="connection-status" class="connection-status" role="status"></div><h3>Generation settings</h3><p class="fine">Saved values apply to chat, drafting, coding proposals and explicit tool plans. A token is a piece of text, not necessarily a word. A low response limit can truncate code or JSON; request a smaller task or raise the limit.</p><div class="form-grid">${field('Temperature · 0 to 2','lm-temperature','number',lm.temperature??0.2)}${field('Response limit · 1 to 16,384 tokens','lm-max-tokens','number',lm.max_tokens??2048)}${field('Request timeout · 1 to 300 seconds','lm-timeout','number',lm.timeout_seconds??60)}</div><div class="route-tabs"><select id="lm-preset" aria-label="Generation preset"><option value="precise">Precise · 0.1 / 2048 tokens</option><option value="balanced" selected>Balanced · 0.2 / 2048 tokens</option><option value="creative">Creative · 0.8 / 4096 tokens</option></select>${button('Apply preset to form','model-preset')}${button('Save local model settings','save-model-options')}</div><h3>Per-model profile</h3><p class="fine">Save the three generation values under the exact model identifier. Selecting a model with a saved profile loads it into this form; save or test to activate it. Profiles do not load or download models.</p><p id="model-profile-status" class="fine"></p><div class="route-tabs">${button('Load saved profile','model-profile-load')}${button('Save profile & activate','model-profile-save')}${button('Delete saved profile','model-profile-delete')}</div><h3>Connection diagnostics</h3><p class="fine">If a model fails to load, open LM Studio’s Local Server / Model Server, load the model manually and inspect Server Logs. Developer settings alone do not start the server. Listing and the tiny inference test are separate checks.</p><div class="route-tabs">${button('Show local diagnostics','model-diagnostics')}${button('Copy shown diagnostics','model-diagnostics-copy')}</div><pre id="model-diagnostics" class="tool-result">No diagnostics requested. This report never includes project files or credentials.</pre><p class="fine">Only loopback endpoints are accepted. Refresh is read-only. Test selected model sends a tiny inference prompt and may cause LM Studio to load it; no project files or tools are sent. Changes in this section are saved before each test. Verification reflects the last test, not continuous monitoring.</p></div><div class="tool-card"><h2>Research domain policy</h2><label class="field"><span><input type="checkbox" id="research-enabled" ${research.enabled?'checked':''} style="width:auto"> Enable controlled public HTTPS research</span></label><div class="form-grid">${field('Allowed domains · one per line','allowed-domains','textarea',(research.allowed_domains||[]).join('\n'))}${field('Denied domains · one per line','denied-domains','textarea',(research.denied_domains||[]).join('\n'))}</div></div><div class="tool-card"><h2>Project memory</h2><label><input id="use-context" type="checkbox" ${c.project_memory?.use_context?'checked':''}> Use saved project context in local model tasks</label><br><label><input id="record-history" type="checkbox" ${c.project_memory?.record_history!==false?'checked':''}> Record task history locally</label></div><div class="route-tabs">${button('Save settings','save-settings')}<button class="action" data-view="permissions">Permission policies →</button></div><p class="safety">SAFE MODE is always on. This release has no unrestricted autonomous mode.</p>`;updateConnectionPanel(snapshot?.connection||{});$('available-models').addEventListener('change',()=>{if($('available-models').value)$('lm-model').value=$('available-models').value;applySavedModelProfile(false);});configureModelOptions();}
 else if(name==='security'){const c=snapshot?.config?.security||{};const state=snapshot?.security||{};body.innerHTML=tabs()+`<div class="tool-card"><h2>Session capabilities</h2><p class="fine">Profiles restrict the saved policies; they cannot grant permissions. Scope resets to Standard when the app restarts and remains active across workspace changes.</p><label class="field">Session profile<select id="session-profile"><option value="standard">Standard · saved policies</option><option value="read_only">Read-only workspace · no host tests or remote writes</option><option value="sandbox_only">Sandbox export only · no host tests or remote writes</option></select></label>${button('Apply session profile','session-profile')}<pre id="security-live" class="tool-result"></pre></div><div class="tool-card"><h2>Protected paths & tool scopes</h2><label><input type="checkbox" id="protect-secrets" ${c.protect_secret_files!==false?'checked':''}> Protect .env, private keys and credential folders from built-in file access</label>${field('Denied files or folders · exact relative paths, one per line','denied-paths','textarea',(c.denied_paths||[]).join('\n'))}${field('Disabled tool or permission actions · one per line','denied-tools','textarea',(c.denied_tools||[]).join('\n'))}<p class="fine">Path rules affect built-in file tools, model file context and Sandbox input export. Approved host code is outside this boundary. Git operations refuse repositories containing protected files to prevent diff/commit disclosure. Broker files are always protected.</p>${button('Save protected scopes','save-security')}<button class="action" data-view="permissions">Edit Allow / Ask / Deny →</button></div><div class="tool-card"><h2>Security review</h2>${field('Selected files · one per line','security-paths','textarea')}<p class="fine">Bounded static heuristics; no code execution. Findings include categories and line numbers, never source snippets or credential values.</p>${button('Review selected files','security-review')}</div><div class="tool-card"><h2>Execution boundary</h2><p class="fine">Host tests run on your PC with approval. Sandbox export creates a .wsb session with network and clipboard disabled, read-only inputs, and one host-writable Results folder. Export does not launch or verify Windows Sandbox.</p>${button('Check boundary status','sandbox-status')}${button('Export approved Sandbox tests','sandbox-export')}<pre class="tool-result">${esc(JSON.stringify(state.sandbox||{},null,2))}</pre></div><div class="tool-card"><h2>Local secrets storage</h2><p class="fine">Windows current-user DPAPI storage. Values are never returned to the UI, models, tests or tools. This release stores credentials for future integrations; LM Studio and Git continue using their existing authentication. No plaintext fallback. Names are visible in metadata and audit logs.</p>${field('Credential name','secret-name')}${field('Credential value','secret-value','password')}<div class="route-tabs">${button('Encrypt & save / replace','secret-save')}${button('Delete named credential','secret-delete')}</div><pre id="secret-list" class="tool-result"></pre></div>`+output();$('session-profile').value=state.profile||'standard';updateSecurity(state);}
 else if(name==='recovery'){settingsReview=null;body.innerHTML=tabs()+`<div class="tool-card"><h2>Release candidate checks</h2><p class="fine">Verify packaged files against the local manifest. This detects changes and missing files; it is not a digital signature or Windows acceptance.</p>${button('Run candidate checks','candidate-checks')}${button('Inspect release trust','release-trust')}${button('Copy shown trust report','copy-release-trust')}<pre id="release-trust-report" class="tool-result">No trust report requested.</pre></div><div class="tool-card"><h2>Settings recovery</h2><p class="fine">Settings are backed up before saved changes. Restore requires a fresh review and mandatory approval, with stale-state checks and a rollback backup. Workspace files and credentials are not restored.</p>${button('Create settings checkpoint','settings-backup')}${button('List checkpoints','settings-backups')}<div id="settings-backup-list"></div>${field('Settings backup ID','settings-backup-id')}<div class="route-tabs">${button('Preview checkpoint restore','settings-preview')}${button('Preview default settings reset','settings-reset')}${button('Apply reviewed settings recovery','settings-restore')}</div><p class="fine">If the app cannot open, run Recover-Settings.bat. Default reset retains a readable workspace setting. All changed policies and destinations are shown for review.</p></div><div class="tool-card"><h2>Workspace snapshots</h2>${button('List file snapshots','recovery-snapshots')}${field('Selected snapshot ID','recovery-snapshot-id')}<div class="route-tabs">${button('Prepare file rollback','recovery-prepare')}${button('Review full rollback diff','review')}${button('Restore reviewed snapshot','recovery-restore')}</div><p class="fine">A file rollback stages a proposal. Review its full diff before approval. Changed files cause conflict rejection rather than silent overwrite. Pending edits must be applied or discarded before preparing rollback.</p></div>`+output();$('settings-backup-id').addEventListener('input',()=>settingsReview=null);}
 else if(name==='permissions'){body.innerHTML=`<div class="tool-card"><h2>Allow / Ask / Deny</h2><p class="fine">Changes apply only when you press Save. Mandatory approval gates still apply to file application and test execution.</p>${Object.entries(snapshot?.policies||{}).map(([key,value])=>`<label class="policy-row"><span>${esc(key.replace(/_/g,' '))}</span><select data-policy="${esc(key)}">${['allow','ask','deny'].map(v=>`<option value="${v}" ${v===value?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label>`).join('')}</div>${button('Save permission policies','save-policies')}<button class="action" data-view="security">Security & Sandbox Center →</button>`;}
 else if(name==='activity'){body.innerHTML='<div class="tool-card"><h2>Latest audit entries</h2><pre class="tool-result">'+esc(JSON.stringify(snapshot?.events||[],null,2))+'</pre>'+button('Refresh','refresh-activity')+'</div>';}
}
const examples={index_workspace:{},snapshot_workspace:{label:'Manual checkpoint'},list_snapshots:{},prepare_restore:{snapshot_id:''},restore_snapshot:{proposal_id:''},rename_python_function:{path:'source.py',old:'old_name',new:'new_name'},export_sandbox_tests:{framework:'auto',timeout_seconds:120},retrieve_memory:{query:''},delete_memory:{entry_id:'',expected_revision:0},clear_memory:{scope:'saved',expected_generation:0},read_web_source:{source_id:''},clear_web_sources:{expected_ids:[]}};
function updateSecurity(state){if(!state)return;const live=$('security-live');if(live)live.textContent=`Active session: ${state.profile}\nRestricted actions: ${(state.restrictions||[]).join(', ')||'None beyond saved policies'}\nSAFE MODE · mandatory approvals remain active`;const list=$('secret-list');if(list)list.textContent=JSON.stringify(state.secrets||[],null,2);}
