function pluginFormKey(){if(!$('plugin-id')||!$('plugin-inputs'))return null;try{return JSON.stringify({plugin_id:val('plugin-id'),inputs:JSON.parse($('plugin-inputs').value)});}catch{return null;}}
function gitArgs(){return {repo:val('git-repo'),operation:val('git-operation'),name:val('git-branch'),base:val('git-base'),message:val('git-message'),title:val('git-title'),tag:val('git-tag'),body:$('git-body').value,draft:$('git-draft').checked};}
function gitFormKey(){return $('git-repo')?JSON.stringify(gitArgs()):null;}
async function runPlugin(name,args={}){if(snapshot?.busy)return toast('Wait for the active operation.');const r=await call('start_job','plugin',{name,...args});if(!r.ok)return toast(r.message);currentJob={id:r.id,name:'plugin_'+name,view:activeView,reviewKey:name==='preview'?JSON.stringify(args):null};if($('tool-output'))$('tool-output').textContent='Working…';await poll();}
async function runRecovery(name,args={}){if(snapshot?.busy)return toast('Wait for the active operation.');const r=await call('start_job','recovery',{name,...args});if(!r.ok)return toast(r.message);currentJob={id:r.id,name:'recovery_'+name,view:activeView,reviewKey:args.backup_id||null};if($('tool-output'))$('tool-output').textContent='Working…';await poll();}
async function runTool(name,args={}){if(snapshot?.busy)return toast('Wait for the active task to finish.');try{const editorKey=workspaceEditorKey();const codingKey=codingFormKey();const testKey=testFormKey();const memoryKey=memoryFormKey();const researchKey=researchFormKey();const result=await call('start_job','tool',{name,args});if(!result.ok)return toast(result.message);const body=activeView==='chat'?addMessage('assistant',`${name.replace(/_/g,' ')}…`):null;currentJob={id:result.id,name,view:activeView,body,editorKey,codingKey,testKey,memoryKey,researchKey,reviewKey:name==='git_preview'?JSON.stringify(args):null};if($('tool-output'))$('tool-output').textContent='Running…';await poll();}catch(error){toast(error.message);}}
function renderBackups(rows){const list=$('settings-backup-list');if(!list)return;list.replaceChildren();for(const row of rows||[]){const b=document.createElement('button');b.className='file-row';b.textContent=`${row.valid?'✓':'Invalid'} · ${row.label||row.id} · ${row.created_at||''}`;b.disabled=!row.valid;b.addEventListener('click',()=>{$('settings-backup-id').value=row.id;settingsReview=null;});list.append(b);}if(!list.children.length)list.textContent='No settings checkpoints yet.';}
function renderFiles(data){workspaceFiles=Array.isArray(data)?data.map(row=>typeof row==='string'?row:row.path):[];workspaceSelected=new Set([...workspaceSelected].filter(path=>workspaceFiles.includes(path)));workspaceTree();}

function renderMemory(data){renderKnowledgeMemory(data);}
function renderSources(data){renderKnowledgeSources(data);}
const val=id=>$(id).value.trim(),paths=id=>val(id).split(id==='code-paths'?/[\r\n]+/:/[,\r\n]+/).map(x=>x.trim()).filter(Boolean);
async function action(name){try{switch(name){
case 'plugin-list':return runPlugin('list');
case 'plugin-preview':pluginReview=null;return runPlugin('preview',{plugin_id:val('plugin-id'),inputs:JSON.parse($('plugin-inputs').value)});
case 'plugin-run':if(!pluginReview)return toast('Review the current workflow first.');return runPlugin('execute',{review_id:pluginReview.id});
case 'plugin-cancel':{const r=await call('cancel_plugin');toast(r.message);break;}
case 'release-trust':return runRecovery('trust');
case 'copy-release-trust':return copyChatText($('release-trust-report').textContent);
case 'candidate-checks':return runRecovery('readiness');
case 'settings-backup':return runRecovery('backup');
case 'settings-backups':return runRecovery('list_backups');
case 'settings-preview':settingsReview=null;return runRecovery('preview_restore',{backup_id:val('settings-backup-id')});
case 'settings-reset':settingsReview=null;return runRecovery('preview_reset');
case 'settings-restore':if(!settingsReview)return toast('Preview and review settings recovery first.');return runRecovery('restore',{review_id:settingsReview.id});
case 'recovery-snapshots':return runTool('list_snapshots');
case 'recovery-prepare':lastReview=null;return runTool('prepare_restore',{snapshot_id:val('recovery-snapshot-id')});
case 'recovery-restore':if(!lastReview||lastReview.kind!=='restore')return toast('Review the full current rollback diff first.');return runTool('restore_snapshot',{proposal_id:lastReview.id});
case 'session-profile':{const r=await call('set_session_profile',val('session-profile'));toast(r.message);await poll();break;}
case 'save-security':{const r=await call('save_settings',{security:{protect_secret_files:$('protect-secrets').checked,denied_paths:paths('denied-paths'),denied_tools:paths('denied-tools')}});toast(r.message);await poll();break;}
case 'security-review':return runTool('security_review',{paths:paths('security-paths')});
case 'sandbox-status':return runTool('sandbox_status');
case 'sandbox-export':return runTool('export_sandbox_tests',{timeout_seconds:120});
case 'secret-save':case 'secret-delete':{const input=$('secret-value');const value=input.value;input.value='';const r=await call('manage_secret',name==='secret-save'?'save':'delete',val('secret-name'),name==='secret-save'?value:null);toast(r.message);await poll();break;}
case 'git-status':return runTool('git_status',{repo:val('git-repo')});
case 'git-diff':case 'git-staged':return runTool('git_diff',{repo:val('git-repo'),staged:name==='git-staged'});
case 'git-preview':gitProposal=null;return runTool('git_preview',gitArgs());
case 'git-execute':if(!gitProposal)return toast('Prepare and review the current operation first. Editing the form requires a new preview.');return runTool('git_execute',{proposal_id:gitProposal.id});
case 'choose-workspace':return protectUnsaved(async()=>{const r=await call('choose_workspace');toast(r.message);if(r.ok){lastReview=null;await poll();view('workspace',true);}});
case 'list-files':return runTool('list_files');
case 'read-file':return protectUnsaved(()=>{rememberForm();runTool('preview_file',{path:val('file-path')});});
case 'stage-file':invalidateWorkspaceReview();return runTool('write_file',{path:val('file-path'),content:$('file-content').value});
case 'review':return runTool('review_changes');
case 'apply':if(!lastReview)return toast('Review the current full diff before applying it.');return runTool('apply_changes',{proposal_id:lastReview.id});
case 'discard':invalidateWorkspaceReview();return runTool('discard_changes');
case 'snapshot':return runTool('snapshot_workspace',{label:'Manual checkpoint'});
case 'analyze-code':return runTool('analyze_code',{paths:paths('code-paths')});
case 'prepare-team':case 'prepare-team-retry':return preparePlan(name==='prepare-team-retry');
case 'start-team':case 'retry-team':return startReviewedPlan(name==='retry-team');
case 'pause-team':case 'resume-team':{const r=await call('control_team',name==='pause-team'?'pause':'resume');toast(r.message);await poll();break;}
case 'cancel-team':{const r=await call('cancel_team');toast(r.message);break;}
case 'propose-code':if(!codingValidation||codingValidation.key!==codingFormKey())return toast('Validate the current selected sources before generating.');invalidateWorkspaceReview();return runTool('propose_code_changes',{paths:paths('code-paths'),instruction:val('code-instruction'),expected_hashes:codingValidation.hashes});
case 'detect-tests':return runTool('detect_test_framework');
case 'preview-tests':testPreviewKey=null;return runTool('preview_tests',testOptions());
case 'run-tests':if(testPreviewKey!==testFormKey())return toast('Preview the current test command before requesting execution.');return runTool('run_tests',testOptions());
case 'cancel-tests':{const r=await call('cancel_tests');return toast(r.message);}
case 'preview-url':return runTool('preview_web',{url:val('research-url')});
case 'fetch-url':return runTool('fetch_web',{url:val('research-url')});
case 'list-sources':return runTool('list_web_sources');
case 'research-context':return runTool('preview_research_context',{source_ids:paths('source-ids'),question:val('research-question')});
case 'research-brief':if(!researchPreview||researchPreview.key!==researchFormKey())return toast('Preview the current research context before creating a draft.');return runTool('create_research_brief',{source_ids:paths('source-ids'),question:val('research-question'),expected_fingerprint:researchPreview.fingerprint});
case 'list-memory':return runTool('list_memory',{query:val('memory-query'),kind:val('memory-filter')});
case 'save-memory':return runTool('save_memory',{kind:val('memory-kind'),title:val('memory-title'),body:$('memory-body').value,...(editingMemory?{entry_id:editingMemory.id,expected_revision:editingMemory.revision}:{})});
case 'memory-new':return newMemoryEntry();
case 'memory-context':return runTool('preview_project_context',{query:val('memory-context-query')});
case 'model-context':return showModelContext();
case 'model-preset':{const presets={precise:[0.1,2048],balanced:[0.2,2048],creative:[0.8,4096]};const preset=presets[val('lm-preset')];markFormTouched();$('lm-temperature').value=preset[0];$('lm-max-tokens').value=preset[1];toast('Preset applied to form. Save to activate.');break;}
case 'save-model-options':{const r=await call('save_settings',{lm_studio:modelSettingsFromForm()});toast(r.message);await poll();break;}
case 'model-profile-load':applySavedModelProfile(true);break;
case 'model-profile-save':case 'model-profile-delete':{const settings=modelSettingsFromForm();const profiles=Object.assign(Object.create(null),snapshot?.config?.lm_studio?.profiles||{});if(name==='model-profile-delete')delete profiles[settings.model];else profiles[settings.model]={temperature:settings.temperature,max_tokens:settings.max_tokens,timeout_seconds:settings.timeout_seconds};const r=await call('save_settings',{lm_studio:name==='model-profile-delete'?{profiles}:{...settings,profiles}});toast(r.ok?(name==='model-profile-delete'?'Saved profile deleted. Active settings are unchanged.':'Model profile saved and activated.'):r.message);await poll();updateProfileStatus();break;}
case 'model-diagnostics':{const r=await call('model_diagnostics');if(r.ok)$('model-diagnostics').textContent=JSON.stringify(r.data,null,2);else toast(r.message);break;}
case 'model-diagnostics-copy':{if($('model-diagnostics').textContent.startsWith('{'))await copyChatText($('model-diagnostics').textContent);else toast('Show diagnostics before copying.');break;}
case 'refresh-models':case 'test-model':{
 const saved=await call('save_settings',{lm_studio:modelSettingsFromForm()});
 if(!saved.ok)return toast(saved.message);
 const r=await call('probe_model',name==='test-model');toast(r.message);await poll();break;
}
case 'save-settings':{const changes={lm_studio:modelSettingsFromForm(),research:{enabled:$('research-enabled').checked,allowed_domains:val('allowed-domains').split('\n').map(x=>x.trim()).filter(Boolean),denied_domains:val('denied-domains').split('\n').map(x=>x.trim()).filter(Boolean)},project_memory:{use_context:$('use-context').checked,record_history:$('record-history').checked}};const r=await call('save_settings',changes);toast(r.message);await poll();break;}
case 'save-policies':{const permissions={};document.querySelectorAll('[data-policy]').forEach(s=>permissions[s.dataset.policy]=s.value);const r=await call('save_settings',{permissions});toast(r.message);await poll();break;}
case 'advanced':return runTool(val('advanced-name'),JSON.parse($('advanced-args').value));
case 'refresh-activity':await poll();view('activity');break;
}}catch(error){toast(error.message);}}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view)view(b.dataset.view);if(b.dataset.mode){mode=b.dataset.mode;view('chat');toast(mode==='Creative Tools'?'Creative text drafts need an enabled local model.':'General Assist selected.');$('prompt').placeholder=mode==='Creative Tools'?'Describe the text you want your local model to draft...':'Type a message, ask a question, or give a command...';}if(b.dataset.window){const close=()=>call('window_action',b.dataset.window).catch(e=>toast(e.message));if(b.dataset.window==='close')protectUnsaved(close);else close();}if(b.dataset.tool)runTool(b.dataset.tool);if(b.dataset.action)action(b.dataset.action);});
$('search').addEventListener('keydown',event=>{if(event.key!=='Enter')return;const q=$('search').value.toLowerCase();const map=[['recovery','recovery'],['release candidate','recovery'],['security','security'],['sandbox','security'],['git','git'],['setting','settings'],['permission','permissions'],['memory','memory'],['research','research'],['code','coding'],['test','terminal'],['file','workspace'],['workspace','workspace'],['agent','agents'],['plugin','plugins'],['action','activity'],['chat','chat']];const match=map.find(([word])=>q.includes(word));if(match)view(match[1]);else{view('chat');const messages=[...document.querySelectorAll('.message-text,.bubble p')];const found=messages.find(n=>n.textContent.toLowerCase().includes(q));if(found)found.scrollIntoView({block:'center'});else toast('No matching conversation or tool.');}});
async function boot(){nativeAPI=window.pywebview?.api||null;if(!nativeAPI)return;clearTimeout(bridgeTimeout);await call('ui_ready');await poll();await initializeGuide();await initializeConversations();setInterval(async()=>{await poll();},600);}
const bridgeTimeout=setTimeout(()=>toast('Desktop connection did not start. Run Diagnose-Startup.bat for the startup report.'),12000);
addEventListener('pywebviewready',boot);if(window.pywebview?.api)boot();
// Read-only rendering harness can inject a bridge before load; no demo execution API ships.
window.PurpleDragonUI={view:(...args)=>view(...args),patchState};

// Keyboard commands do not approve operations; Escape always rejects an open approval.
addEventListener('keydown',event=>{
 if(event.key==='Escape'){
  if(document.getElementById('approval').open)return;
  if(activeView!=='chat'){event.preventDefault();view('chat');}
 }else if(event.ctrlKey&&event.key==='1'){event.preventDefault();view('chat');}
 else if(event.ctrlKey&&event.key==='2'){event.preventDefault();view('tools');}
 else if(event.ctrlKey&&event.key===','){event.preventDefault();view('settings');}
});

function updateConnectionPanel(connection){
 const status=document.getElementById('connection-status');if(!status)return;
 const titles={disabled:'Connector disabled',configured:'Configured · not tested',testing:'Checking local server',server_ready:'Server reachable · inference unverified',verified:'Selected model verified',no_models:'Server reachable · no models',error:'Connection test failed'};
 status.replaceChildren();const title=document.createElement('strong');title.textContent=titles[connection.status]||'Not tested';const detail=document.createElement('p');detail.textContent=connection.message||'Use Refresh models to check the saved endpoint.';status.append(title,detail);const target=document.createElement('p');target.textContent='Saved target: '+(snapshot?.config?.lm_studio?.model||'—')+' · '+(connection.models||[]).length+' identifier(s) listed. Loaded state is not reported.';status.append(target);if(connection.busy&&connection.started_at){const progress=document.createElement('p');progress.textContent=(connection.phase==='inference'?'Waiting for model inference; it may be loading':'Reading server model list')+' · '+Math.max(0,Math.floor(Date.now()/1000-connection.started_at))+'s elapsed · request timeout '+connection.timeout_seconds+'s';status.append(progress);}if(connection.error_code){const error=document.createElement('small');error.textContent='Diagnostic code: '+connection.error_code;status.append(error);}
 if(connection.checked_at){const stamp=document.createElement('small');stamp.textContent='Last checked '+new Date(connection.checked_at).toLocaleString()+(connection.latency_ms!=null?' · listing '+connection.latency_ms+' ms':'')+(connection.inference_ms!=null?' · inference '+connection.inference_ms+' ms':'');status.append(stamp);}
 status.className='connection-status '+(connection.status==='error'?'error':connection.status==='verified'?'success':'');
 const select=document.getElementById('available-models');const models=connection.models||[];const key=JSON.stringify(models);
 if(select&&select.dataset.models!==key){const current=select.value;select.replaceChildren();const empty=document.createElement('option');empty.value='';empty.textContent=models.length?'Select an available model':'No models discovered';select.append(empty);for(const id of models){const option=document.createElement('option');option.value=id;option.textContent=id;select.append(option);}if(models.includes(current))select.value=current;select.dataset.models=key;}
 for(const b of document.querySelectorAll('[data-action="refresh-models"],[data-action="test-model"]'))b.disabled=!!connection.busy;
}
